import React, { useState } from 'react';

// Create the MultiStepForm component here
function MultiStepForm(): JSX.Element {
  // Define the steps array here
  const steps = ['Step 1', 'Step 2', 'Step 3'];

  // Initialize currentStep state here
  const [currentStep, setCurrentStep] = useState<number>(0);

  // Create handleNext function here
  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    }
  };

  // Create handlePrevious function here
  const handlePrevious = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  return (
    <div>
      <h1>Multi-Step Form</h1>
      <p>Step {currentStep + 1} of {steps.length}</p>
      <h2>{steps[currentStep]}</h2>
      <button onClick={handlePrevious}>Previous</button>
      {/* Add Next button here */}
    </div>
  );
}

export default MultiStepForm;

